ANNOTATIONS = [
    (1, 'before', '''通用树形选择器。核心手法只有一句话：把树按「当前展开状态」深度优先拍平成普通选项列表，然后整个交给 Select 渲染。所以这个文件里没有任何绘制代码，全是「拍平 / 反查 / 左右键」。上下键、翻页、取消、数字直选全部由 Select 免费提供。'''),
    (5, 'before', '''复用 CustomSelect 的 Select。这条依赖决定了整个组件的分层：树只负责结构与展开，选中与导航完全外包。'''),
    (6, 'before', '''节点定义。注意 id 与 value 是两个字段：id 用于展开状态与焦点（必须唯一且稳定），value 是业务数据。拍平后传给 Select 的 value 用的是 id 而不是 value——这是本文件最容易看错的一处。'''),
    (15, 'before', '''拍平后的行内结构：多带 depth、isExpanded、hasChildren、parentId 四个字段。parentId 只给左键回退用，depth 只给缩进前缀用。'''),
    (72, 'before', '''isNodeExpanded 是函数而不是集合。这让受控方可以自己决定展开态（比如「默认展开第一层」），而不必构造一个覆盖全部节点的 Set。'''),
    (89, 'before', '''父节点前缀可替换，默认是实心三角与空心三角。把它做成函数而不是常量，是因为有些调用方要用方括号或其他符号表达折叠。'''),
    (96, 'before', '''子节点前缀默认是两个空格加小三角。层级感完全靠缩进表达——终端里没有边框可画，缩进是唯一的层级语言。'''),
    (110, 'before', '''入口，_c(48)。'''),
    (129, 'before', '''三个默认值就地兜底。layout 默认 expanded（每行再带描述），isDisabled 与 hideIndexes 默认 false——注意它们都不是通过参数默认值给的，而是显式三目，方便看出「未传时是什么」。'''),
    (134, 'before', '''空 Set 走哨兵缓存。这一格的意义是：useState 的初始值只需在首次渲染求一次，若每次都新建 Set，虽然 React 会忽略，但编译器仍会保守缓存。'''),
    (140, 'before', '''isProgrammaticFocusRef 用来区分「程序移动焦点」与「用户移动焦点」。左键回退父级时会主动改焦点，如果不打这个标记，Select 的回调会把这个程序动作当成用户操作再上报一次。'''),
    (144, 'before', '''isExpanded 是「受控优先」：只要传了 isNodeExpanded，内部 Set 就完全作废。也就是说这个组件不支持「受控与非受控混用」——不传函数才用内部状态，界线很干脆。'''),
    (158, 'before', '''拍平逻辑本身：依赖展开判定函数和节点树，深度优先只把「已展开节点的子树」放进行内列表。注意它把结果写进闭包变量 result，而不是 return 一个数组——这样能省掉每层递归的数组拼接。'''),
    (170, 'before', '''唯一的裁剪条件：有子节点且当前已展开，才递归下去。折叠节点的整棵子树根本不进入列表，所以 Select 的上下键天然跳过它们。'''),
    (186, 'before', '''两个默认前缀函数都提到模块级，引用稳定。它们被用于 ?? 兜底，若每次渲染新建，会让下面 buildLabel 的记忆槽每次都失效。'''),
    (192, 'before', '''buildLabel 的三分支：有子节点用父前缀、无子节点且不是顶层用子前缀、顶层叶子节点不加前缀。前缀与标签直接拼成字符串，而不是嵌套 JSX——因为 Select 的 label 是纯文本。'''),
    (212, 'before', '''拍平结果转成 Select 的选项。value 取 node.id，所以后面所有回调拿到的都是 id，必须靠 nodeMap 反查回节点。另外 dimDescription 默认 true，说明描述文字默认是暗淡的次要信息。'''),
    (227, 'before', '''nodeMap 供 id 反查节点。展开、聚焦、选中三条路径都要把 id 还原成节点对象，因为对外回调传的是节点而不是 id。'''),
    (237, 'before', '''findFlattenedNode 用线性 find。列表通常只有几十项，二分反而要多维护一个排序不变量——这里选了简单。'''),
    (246, 'before', '''toggleExpand：无子节点直接返回（叶子节点不该有展开动作）；有 onExpand / onCollapse 就完全交给外部，只有非受控时才动内部 Set。'''),
    (255, 'before', '''展开用 new Set(prev).add 造新集合。不可变更新是必须的：React 靠引用比较判断是否重渲染，原地 add 会导致界面不更新。'''),
    (261, 'before', '''折叠同样复制后 delete。注意这里用了两个不同的累加变量名（prev 与 prev_0），是编译器为避免同一函数内重名而生成的。'''),
    (279, 'before', '''键盘处理器只接管左右键，上下键一概不管——因为上下键归 Select。这是「组合而非重写」的具体体现：两个组件分别持有自己的键位。'''),
    (280, 'before', '''focusNodeId 为空或整体禁用时直接返回。左右键的动作全部依赖「当前聚焦的是哪个节点 id」，而这个 id 由父组件通过 props 传进来——也就是说父组件必须把 Select 的 onFocus 结果回灌成 focusNodeId，左右键才有效。'''),
    (287, 'before', '''右方向键：有子节点就展开。注意它不移动焦点——展开后子节点出现在下一行，用户还需要按一次下键才进去，这符合文件树的习惯。'''),
    (296, 'before', '''左方向键在「叶子节点或已折叠」的情况下做两件事：折叠父节点、把焦点交给父节点。这个组合行为值得留意——它同时改变了展开状态和焦点位置，读代码时容易只看出一半。'''),
    (340, 'before', '''聚焦回调有两道闸：先看 isProgrammaticFocusRef（程序移动则吞掉这次上报），再看 lastFocusedIdRef（同一个 id 不重复上报）。两道闸分别防止「左键回退触发两次 onFocus」和「重渲染时重复上报」。'''),
    (365, 'before', '''传给 Select 的 props 几乎原样透传，只把 options 换成拍平结果、defaultFocusValue 换成 focusNodeId。注意 onFocus 传的是经过两道闸处理后的 handleFocus，而不是原始 onFocus。'''),
    (382, 'before', '''最外层 Box 要 tabIndex 与 autoFocus 才收得到左右键。因为左右键的处理在本组件而不是 Select 里，不主动抢焦点就永远收不到——这和上一批 Shell 详情是同一个坑。'''),
]
